export const BRUNNEL = "";

/** Decode the delta-encoded polyline into lat/lon pairs. */
function decode(encoded: string): [number, number][] {
  const points: [number, number][] = [];
  let index = 0;
  let lat = 0;
  let lon = 0;
  while (index < encoded.length) {
    let shift = 0;
    let result = 0;
    let byte: number;
    do {
      byte = encoded.charCodeAt(index++) - 63;
      result |= (byte & 0x1f) << shift;
      shift += 5;
    } while (byte >= 0x20);
    lat += result & 1 ? ~(result >> 1) : result >> 1;

    shift = 0;
    result = 0;
    do {
      byte = encoded.charCodeAt(index++) - 63;
      result |= (byte & 0x1f) << shift;
      shift += 5;
    } while (byte >= 0x20);
    lon += result & 1 ? ~(result >> 1) : result >> 1;

    points.push([lat / 1e5, lon / 1e5]);
  }
  return points;
}

export const railRoute: [number, number][] = decode(GEOMETRY);

export type Brunnel = "bridge" | "tunnel" | null;
export const brunnelAt = (i: number): Brunnel =>
  BRUNNEL[i] === "t" ? "tunnel" : BRUNNEL[i] === "b" ? "bridge" : null;
